-- A57: batch b001_fr, chunk 1 (25 videos for learners of fr). Guarded: nothing is written when a row of
-- this chunk exists already (the whole transaction stops); English (media_exercise_sets) is not touched.
begin;
do $g$ begin
  if exists (select 1 from public.media_exercise_sets_l10n where learning_language = 'fr' and media_id in (209,142,163,429,531,4658,852,646,5580,844,5468,5215,694,757,5456,118,706,395,4243,617,10,792,7193,365,5616)) then
    raise exception 'A57 out/b001_fr_01.sql: rows exist already - nothing written';
  end if;
end $g$;
do $g$ begin
  if (select count(*) from public.media_exercise_sets_l10n where learning_language = 'fr' and media_id in (209,142,163,429,531,4658,852,646,5580,844,5468,5215,694,757,5456,118,706,395,4243,617,10,792,7193,365,5616)) <> 25 then
    raise exception 'A57 out/b001_fr_01.sql: not 25 rows after the insert';
  end if;
end $g$;
commit;
